def target(f,text,d):
 r=d.get(norm(f))
 if not r:raise KeyError(f)
 return {'id':f"ar-r{r['rank']}",'form':f,'lemma':f,'part_of_speech':r.get('part_of_speech_source'),'intended_sense':PREFERRED[f],'register':'contemporary standard','variety':'MSA','context_strategy':['contrast','cause_consequence','scenario_resolution'],'first_introduced':True,'exposures_in_text':max(1,text.count(f)),'source_lexicon':r.get('source_file'),'source_rank':r['rank'],'beyond_base':False}
def qa(items):
 q=[];a=[]
 for i,(t,p,x,ids) in enumerate(items,1):
  z={'id':f'q{i}','type':t,'prompt':p,'answer_id':f'a{i}'}
  if ids:z['target_ids']=ids
  q.append(z);a.append({'id':f'a{i}','question_id':f'q{i}','answer':x,'explanation':''})
 if len(q)!=10:raise ValueError('ten questions required')
 return q,a
